-- =============================================================================
-- 530 — LE CAHIER D'EXERCICES DE 1RE (partie 18)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/1re/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 530 --niveau 1re --fichiers francais.n2a,francais.n2b,francais.n3a,francais.n3b,francais.n4a --suffixe 18 > supabase/contenu/530_exercices_1re_18.sql
--
-- 90 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   francais.n2a            18 exercices · 6 chapitres
--   francais.n2b            18 exercices · 6 chapitres
--   francais.n3a            18 exercices · 6 chapitres
--   francais.n3b            18 exercices · 6 chapitres
--   francais.n4a            18 exercices · 6 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('ac40112c-efda-5ad2-84ef-d94bdf1aded1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Dix volumes pour un seul roman","competence":"analyser-document","situation":"Tu prépares une fiche sur le plus long roman de la littérature française. Relève ses chiffres, puis démêle qui se cache derrière ses héros.","documents":[{"id":"fiche","type":"fiche","modele":"affiche","entete":"Artamène ou le Grand Cyrus","sousTitre":"Un roman sous le nom de Georges de Scudéry","emoji":"📚","lignes":[{"id":"z1","texte":"Nombre de volumes","valeur":"Dix"},{"id":"z2","texte":"Publication","valeur":"1649 à 1653"},{"id":"z3","texte":"Longueur","valeur":"environ deux millions de mots"},{"id":"z4","texte":"Cadre","valeur":"L’Antiquité perse"}],"pied":"Écrit pour l’essentiel par sa sœur Madeleine","teinte":"violet"},{"id":"cles","type":"tableau","titre":"Les clés du roman","colonnes":["Personnage du roman","Ce que les lecteurs y reconnaissent","Précision"],"lignes":[["Cyrus","Le Grand Condé","Héros militaire de la Fronde"],["Mandane","?","Sa sœur"],["Sapho","?","Peinte dans le dernier volume"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui donne le nombre de volumes du roman.","aide":"Cherche le mot « volumes » dans la fiche.","type":"zone","document":"fiche","multiple":false},{"enonce":"Combien d’années s’écoulent entre le premier et le dernier volume, d’après les dates de la fiche ?","aide":"Soustrais la première date de la dernière.","type":"nombre","unite":"ans"},{"enonce":"Complète les deux cases « ? » du tableau.","aide":"Mandane est la sœur du Grand Condé ; Sapho est le surnom de l’autrice.","type":"trous","segments":["Mandane est ",0," ; Sapho est ",1,"."],"banque":["Cyrus","duchesse de Longueville","Georges de Scudéry","Madeleine de Scudéry"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le roman compte **dix volumes** : c’est ce qui en fait le plus long roman de la littérature française."},{"cle":{"type":"nombre","valeur":4,"tolerance":0},"affichage":"4 ans","explication":"1653 − 1649 = **4 ans** : les dix volumes paraissent en quatre ans seulement."},{"cle":{"type":"trous","trous":[["duchesse de longueville","la duchesse de longueville"],["madeleine de scudery"]]},"affichage":"duchesse de longueville · madeleine de scudery","explication":"**Mandane** est la **duchesse de Longueville**, sœur du Grand Condé ; **Sapho** est **Madeleine de Scudéry** elle-même : c’est un roman à clé."}]$ex$::jsonb),
  ('ac40112c-efda-5ad2-84ef-d94bdf1aded1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un samedi dans le salon de Sapho","competence":"se-reperer-temps","situation":"Un samedi de 1652, on lit un nouveau volume du Grand Cyrus chez Madeleine de Scudéry. Que cherche-t-on dans ce roman, et où se situe-t-il dans le siècle ?","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Une lecture en société","blocs":["Dans le Marais, les invités se pressent pour la lecture du jour. Les batailles et les enlèvements passent vite : tout le monde les attend, personne ne les écoute.","On s’arrête sur une conversation : « l’absence renforce-t-elle l’amour ? » Chacun reconnaît sous un nom antique un personnage de la Cour."],"source":"Texte écrit pour l’exercice"},{"id":"frise","type":"frise","titre":"Le Grand Cyrus parmi son siècle","debut":1645,"fin":1680,"pas":5,"periodes":[{"id":"z1","debut":1648,"fin":1653,"nom":"La Fronde","teinte":"ambre"}],"evenements":[{"id":"z2","date":1649,"nom":"Début du Grand Cyrus"},{"id":"z3","date":1659,"nom":"Les Précieuses ridicules"},{"id":"z4","date":1678,"nom":"La Princesse de Clèves"}]}],"questions":[{"enonce":"Touche les deux mots qui nomment ce qui ne sert que de cadre au roman.","aide":"Cherche ce que le public attend sans vraiment l’écouter.","type":"zone","document":"scene","multiple":true},{"enonce":"Range chaque élément du roman : cadre, ou ce qui intéresse vraiment le public ?","aide":"Pense à ce qu’on discute après la lecture, dans le salon.","type":"categories","categories":[{"id":"c0","texte":"Ce qui sert de cadre"},{"id":"c1","texte":"Ce qui intéresse vraiment"}],"items":[{"id":"i0","texte":"Les reconnaissances"},{"id":"i1","texte":"Les naufrages"},{"id":"i2","texte":"Les questions galantes"},{"id":"i3","texte":"Les analyses de sentiments"},{"id":"i4","texte":"Les portraits"}]},{"enonce":"Combien d’années séparent le début du Grand Cyrus de La Princesse de Clèves ?","aide":"Repère les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Remets ces trois repères dans l’ordre où ils se produisent.","aide":"Lis la frise de gauche à droite.","type":"ordre","items":[{"id":"a","texte":"Début du Grand Cyrus"},{"id":"b","texte":"La Princesse de Clèves"},{"id":"c","texte":"Les Précieuses ridicules"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m13","m16"]},"explication":"Les **batailles** et les **enlèvements** ne sont que le cadre ; ce qui compte, ce sont les conversations."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c1"}},"explication":"Naufrages et reconnaissances sont le **cadre** de l’aventure ; **portraits**, **questions galantes** et **analyses de sentiments** font le plaisir du public."},{"cle":{"type":"nombre","valeur":29,"tolerance":0},"affichage":"29 ans","explication":"1678 − 1649 = **29 ans** : le roman de Scudéry est donc très antérieur à celui de Mme de La Fayette."},{"cle":{"type":"ordre","ids":["a","c","b"]},"explication":"Le Grand Cyrus (**1649**), puis la satire de Molière (**1659**), puis le roman classique de **1678**."}]$ex$::jsonb),
  ('ac40112c-efda-5ad2-84ef-d94bdf1aded1'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Pourquoi lire dix volumes ?","competence":"argumenter","situation":"Deux élèves se demandent si le Grand Cyrus mérite encore d’être lu. Le dialogue et le tableau t’aident à tenir une thèse pour ta dissertation.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Sami","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Dix volumes d’enlèvements, c’est interminable : il ne s’y passe rien."},{"qui":"Sami","texte":"Le public ne lisait pas pour l’action. Il venait pour les conversations et pour deviner quelles personnes réelles se cachaient sous les noms antiques."},{"qui":"Léa","texte":"Alors Cyrus n’est pas vraiment Cyrus ?"},{"qui":"Sami","texte":"Pour les lecteurs de la Fronde, c’est le Grand Condé."}]},{"id":"these","type":"tableau","titre":"Deux thèses pour la dissertation","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Un document sur l’art de la conversation","Les débats galants tiennent plus de place que l’action","?"],["Un roman à clé","Les lecteurs reconnaissent des contemporains sous des noms antiques","Cyrus = le Grand Condé"]],"enteteLignes":true}],"questions":[{"enonce":"Touche les deux mots qui disent ce que le public cherche vraiment dans le roman.","aide":"Sami répond à Léa : « il venait pour… et pour deviner… ».","type":"zone","document":"deb","multiple":true},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"On cherche un exemple de débat galant, pas d’aventure.","type":"choix","options":[{"id":"a","texte":"Le roman paraît pendant et juste après la Fronde"},{"id":"b","texte":"Peut-on aimer sans espoir ? L’absence renforce-t-elle l’amour ?"},{"id":"c","texte":"Madeleine de Scudéry signe du nom de son frère Georges"},{"id":"d","texte":"Cyrus enlève Mandane sur un vaisseau, puis la reprend"}],"multiple":false},{"enonce":"Relie chaque trait du roman à ce qu’il révèle.","aide":"Chaque trait a une fonction dans le jeu de salon.","type":"association","gauche":[{"id":"g0","texte":"Le cadre de l’Antiquité perse"},{"id":"g1","texte":"Le portrait de Sapho"},{"id":"g2","texte":"Une lecture par épisodes, en société"}],"droite":[{"id":"d0","texte":"Un plaisir collectif, comme une série"},{"id":"d1","texte":"La défense d’une femme savante"},{"id":"d2","texte":"Un décor sous lequel on reconnaît la société du temps"}]},{"enonce":"Quelle conclusion de dissertation ces documents permettent-ils le mieux d’appuyer ?","aide":"Reprends les deux thèses du tableau : conversation et roman à clé.","type":"choix","options":[{"id":"a","texte":"Le Grand Cyrus est resté célèbre sans interruption jusqu’au XXe siècle"},{"id":"b","texte":"Le roman d’avant La Princesse de Clèves est immense, galant et héroïque"},{"id":"c","texte":"Le Grand Cyrus a été écrit pour condamner la Fronde et ses chefs"},{"id":"d","texte":"Le roman du XVIIe siècle est toujours court et sans aucun héros"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m25","m30"]},"explication":"Le public cherche les **conversations** et les **personnes** réelles à reconnaître : le roman est un jeu de salon."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les **questions galantes** débattues à l’infini illustrent la thèse : la conversation est l’art de vivre du roman."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"Le **décor antique** masque les contemporains, **Sapho** défend l’idée qu’une femme peut être savante, la **lecture en société** fait du roman un plaisir partagé."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le roman montre ce qu’était le genre **avant** 1678 : **immense, galant, héroïque**, nourri de conversations."}]$ex$::jsonb),
  ('b50f6df2-ce44-513e-9e89-28ebdf9ea753'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le grand magasin de Mouret","competence":"analyser-document","situation":"Tu présentes Au Bonheur des Dames à ta classe. Commence par la carte d’identité du roman, puis par ses principaux personnages.","documents":[{"id":"id","type":"fiche","modele":"affiche","entete":"Au Bonheur des Dames","sousTitre":"Émile Zola","emoji":"🏬","lignes":[{"id":"z1","texte":"Publication","valeur":"1883"},{"id":"z2","texte":"Série","valeur":"Les Rougon-Macquart"},{"id":"z3","texte":"Rang dans la série","valeur":"Onzième volume"},{"id":"z4","texte":"Mouvement","valeur":"Naturalisme"}],"pied":"Octave Mouret vient de Pot-Bouille (1882)","teinte":"ambre"},{"id":"pers","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Situation"],"lignes":[["Denise Baudu","Orpheline venue de Valognes"],["Octave Mouret","Patron du grand magasin"],["Baudu","Oncle drapier du « Vieil Elbeuf »"],["Bourras","Vieux marchand de parapluies"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne qui dit à quelle série appartient le roman.","aide":"Zola a écrit toute une « histoire naturelle et sociale d’une famille ».","type":"zone","document":"id","multiple":false},{"enonce":"Complète la fiche du roman.","aide":"Les deux informations sont dans la fiche.","type":"trous","segments":["Au Bonheur des Dames est le ",0," volume des Rougon-Macquart, publié en ",1,"."],"banque":["onzième","1882","1883","vingtième"]},{"enonce":"Relie chaque personnage à son rôle dans l’histoire.","aide":"Un personnage dirige, une autre travaille, deux résistent.","type":"association","gauche":[{"id":"g0","texte":"Denise Baudu"},{"id":"g1","texte":"Octave Mouret"},{"id":"g2","texte":"Baudu"},{"id":"g3","texte":"Bourras"}],"droite":[{"id":"d0","texte":"Dirige le grand magasin"},{"id":"d1","texte":"Devient vendeuse au Bonheur des Dames"},{"id":"d2","texte":"Perd tout, ruiné par le magasin"},{"id":"d3","texte":"Résiste jusqu’à l’expulsion"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Le roman appartient aux **Rougon-Macquart**, la grande série de Zola."},{"cle":{"type":"trous","trous":[["onzieme","11e","11"],["1883"]]},"affichage":"onzieme · 1883","explication":"Le roman est le **onzième** volume de la série et paraît en **1883**."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2","g3":"d3"}},"explication":"**Denise** entre comme vendeuse, **Mouret** dirige, **Baudu** et **Bourras** sont les petits commerçants écrasés."}]$ex$::jsonb),
  ('b50f6df2-ce44-513e-9e89-28ebdf9ea753'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du Vieil Elbeuf à la vente de blanc","competence":"se-reperer-temps","situation":"Denise vient d’arriver à Paris. Suis ce qu’elle découvre, puis ce que le magasin invente pour séduire les clientes.","documents":[{"id":"fil","type":"chaine","titre":"L’histoire de Denise","disposition":"colonne","noeuds":[{"id":"z1","texte":"Denise entre comme vendeuse au Bonheur des Dames"},{"id":"z2","texte":"Elle voit la ruine des petits commerçants"},{"id":"z3","texte":"Mouret, génie du commerce, l’aime"},{"id":"z4","texte":"Denise résiste : pas question d’être maîtresse"},{"id":"z5","texte":"?"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"innov","type":"tableau","titre":"Les innovations du magasin","colonnes":["Innovation","Son ressort"],"lignes":[["Étalages, soldes, publicité","Créer le désir"],["Vente par correspondance","?"],["Exploitation de la clientèle féminine","Le désir comme moteur de vente"]],"enteteLignes":true}],"questions":[{"enonce":"Que faut-il écrire dans la case « ? » de la chaîne, à la fin du roman ?","aide":"Denise a refusé d’être une maîtresse : que reste-t-il ?","type":"choix","options":[{"id":"a","texte":"Elle devient la maîtresse de Mouret"},{"id":"b","texte":"Elle ouvre sa propre boutique de nouveautés"},{"id":"c","texte":"Elle quitte Paris et rentre à Valognes"},{"id":"d","texte":"Elle finit par épouser Mouret"}],"multiple":false},{"enonce":"Touche l’étape où Denise voit ce que le magasin fait aux petits commerçants.","aide":"Cherche le mot « ruine ».","type":"zone","document":"fil","multiple":false},{"enonce":"Quel est le ressort de la vente par correspondance (case « ? » du tableau) ?","aide":"Un catalogue envoyé loin du magasin touche qui ?","type":"choix","options":[{"id":"a","texte":"Fermer les boutiques concurrentes une à une"},{"id":"b","texte":"Étendre le marché au-delà du quartier"},{"id":"c","texte":"Remplacer les vendeuses par des commis"},{"id":"d","texte":"Faire payer les clientes avant de les servir"}],"multiple":false},{"enonce":"Complète la phrase avec le tableau et la chaîne.","aide":"Pense à l’oncle drapier de Denise.","type":"trous","segments":["Le magasin ",0," l’oncle ",1," et les autres petits commerçants du quartier."],"banque":["ruine","enrichit","Baudu","Bourras","Mouret"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"À la fin, Denise **épouse** Mouret : elle n’est jamais devenue sa maîtresse."},{"cle":{"type":"zone","ids":["z2"]},"explication":"À cette étape, Denise découvre la **ruine des petits commerçants**, dont son oncle Baudu."},{"cle":{"type":"choix","ids":["b"]},"explication":"La vente par correspondance sert à **étendre le marché** : on vend à des clientes qui ne viendront jamais en boutique."},{"cle":{"type":"trous","trous":[["ruine"],["baudu"]]},"affichage":"ruine · baudu","explication":"Le grand magasin **ruine** l’oncle **Baudu** et les boutiques voisines."}]$ex$::jsonb),
  ('b50f6df2-ce44-513e-9e89-28ebdf9ea753'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une machine et un temple","competence":"analyser-texte","situation":"Zola décrit le grand magasin comme une machine et comme un temple. Lis une description écrite à sa manière et repère les deux images.","documents":[{"id":"desc","type":"texte","genre":"recit","titre":"Dans la galerie des soieries","blocs":["Sous la verrière, la nef des soieries s’ouvrait comme une église, et les dames, silencieuses, s’approchaient de l’autel de la nouvelle mode.","Derrière les murs, la machine ronflait : le monte-charge, les caisses, les commis alignés, tout tournait pour que le désir ne s’éteigne jamais."],"source":"Texte écrit pour l’exercice, à la manière de Zola"}],"questions":[{"enonce":"Touche les deux mots qui font du magasin un lieu de culte.","aide":"Cherche le vocabulaire de l’église.","type":"zone","document":"desc","multiple":true},{"enonce":"Touche les deux mots qui font du magasin un mécanisme.","aide":"Cherche ce qui ronfle et ce qui tourne sans cesse.","type":"zone","document":"desc","multiple":true},{"enonce":"Dans « C’était la cathédrale du commerce moderne », quelle image domine ?","aide":"Une cathédrale est un lieu de quoi ?","type":"choix","options":[{"id":"a","texte":"Celle de la machine : le commerce est un mécanisme"},{"id":"b","texte":"Celle de la ruine : le commerce détruit les églises"},{"id":"c","texte":"Celle de la prison : le commerce enferme les clientes"},{"id":"d","texte":"Celle du temple : le commerce devient une religion"}],"multiple":false},{"enonce":"Range chaque personnage : victime du magasin, ou bénéficiaire ?","aide":"Pense à celui qui perd sa boutique et à ceux qui font fortune.","type":"categories","categories":[{"id":"c0","texte":"Victime du magasin"},{"id":"c1","texte":"Profite du magasin"}],"items":[{"id":"i0","texte":"Le baron Hartmann"},{"id":"i1","texte":"Geneviève"},{"id":"i2","texte":"Bourras"},{"id":"i3","texte":"Baudu"},{"id":"i4","texte":"Mouret"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m4","m20"]},"explication":"**Nef** et **autel** appartiennent à l’église : le magasin devient un temple, où la mode est une religion."},{"cle":{"type":"zone","ids":["m29","m39"]},"explication":"La **machine** qui **tourne** montre un magasin fait de rouages, au service du désir."},{"cle":{"type":"choix","ids":["d"]},"explication":"La **cathédrale** est l’image du **temple** : le grand magasin attire les foules comme un lieu de culte."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1"}},"explication":"**Baudu**, **Bourras** et **Geneviève** sont écrasés ; **Mouret** et le banquier **Hartmann** profitent du progrès : c’est une loi impitoyable."}]$ex$::jsonb),
  ('29bbccd8-69aa-5e1b-a4a0-03f71cf6b1f1'::uuid, 1, 1, 5, 20, 3,
