  ('22412df0-a8db-5005-bc79-7ccb22c23cbc'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Cultiver son jardin, vraiment ?","competence":"argumenter","situation":"Deux élèves préparent l’oral : la fin de *Candide* est-elle un renoncement, ou un appel à agir ? Lis leur échange et un passage écrit à la manière de Voltaire.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malik","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Cultiver son jardin, c’est se désintéresser du monde : Candide baisse les bras."},{"qui":"Malik","texte":"Regarde : Pangloss ne cesse de discourir sur le meilleur des mondes. Candide, lui, finit par se mettre au travail."},{"qui":"Inès","texte":"Donc Voltaire ne se moque pas du travail ?"},{"qui":"Malik","texte":"Non. Il se moque des systèmes qui n’ont jamais rien changé."}]},{"id":"pastiche","type":"texte","genre":"recit","titre":"Un optimiste devant sa maison","blocs":["Le docteur Trompette, en passant devant la ruine de sa maison, expliquait à ses élèves que tout s’y était passé pour le mieux.","Les murs étaient à terre, mais on y voyait enfin le ciel ; il n’avait plus de dettes, puisqu’il n’avait plus de meubles."],"source":"Texte écrit pour l’exercice, à la manière de Voltaire"}],"questions":[{"enonce":"Touche le mot qui dit ce que Candide choisit de faire à la fin.","aide":"Malik l’oppose au bavardage de Pangloss.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux mots par lesquels l’optimiste présente la ruine comme un bien.","aide":"Cherche les mots qui transforment un désastre en avantage.","type":"zone","document":"pastiche","multiple":true},{"enonce":"Range chaque élément : Voltaire le dénonce, ou le propose ?","aide":"Demande-toi : est-ce un mal du monde, ou une réponse à ce mal ?","type":"categories","categories":[{"id":"c0","texte":"Ce qu’il dénonce"},{"id":"c1","texte":"Ce qu’il propose"}],"items":[{"id":"i0","texte":"« Il faut cultiver notre jardin »"},{"id":"i1","texte":"Les systèmes de Pangloss"},{"id":"i2","texte":"Le fanatisme de l’Inquisition"},{"id":"i3","texte":"La guerre des Bulgares"},{"id":"i4","texte":"Le travail modeste de la métairie"}]},{"enonce":"Quelle lecture de la conclusion le cours permet-il de défendre ?","aide":"Pangloss soutient un système ; Candide, à la fin, a changé de méthode.","type":"choix","options":[{"id":"a","texte":"Il faut renoncer aux grands systèmes et agir par le travail"},{"id":"b","texte":"Il faut fuir le monde pour vivre loin des hommes"},{"id":"c","texte":"Il faut se venger de l’Inquisition et des Bulgares"},{"id":"d","texte":"Il faut tout accepter puisque tout est pour le mieux"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"À la fin, Candide se met au **travail** : la sagesse de la métairie est modeste et pratique."},{"cle":{"type":"zone","ids":["m23","m33"]},"explication":"Le docteur dit que tout est pour le **mieux** et qu’on voit **enfin** le ciel : l’ironie vient de ce faux bon côté, comme chez Pangloss."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c0","i3":"c0","i4":"c1"}},"explication":"Voltaire **dénonce** les systèmes, le fanatisme et la guerre ; il **propose** le travail modeste et le jardin : renoncer aux systèmes et agir."},{"cle":{"type":"choix","ids":["a"]},"explication":"La conclusion est célèbre et discutée : elle invite à **renoncer aux systèmes et à agir**, ce que montre le passage de Pangloss au travail."}]$ex$::jsonb),
