  ('6ee991b6-1148-5de0-8784-defe34a258b7'::uuid, 2, 2, 10, 35, 3,
   $ex${"titre":"Quatre sections, des poèmes d’amour","competence":"analyser-document","situation":"Le recueil réunit des poèmes écrits à plusieurs moments. Retrouve la section manquante, puis relie les poèmes à ce qui les caractérise.","documents":[{"id":"sections","type":"chaine","titre":"Les quatre sections du recueil","disposition":"colonne","noeuds":[{"id":"z1","texte":"Répétitions (1922)"},{"id":"z2","texte":"?"},{"id":"z3","texte":"Les Petits Justes"},{"id":"z4","texte":"Nouveaux poèmes"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]},{"id":"poemes","type":"tableau","titre":"Deux poèmes du recueil","colonnes":["Poème","Son premier vers"],"lignes":[["La courbe de tes yeux…","fait le tour de mon cœur"],["L’amoureuse","?"]],"enteteLignes":true}],"questions":[{"enonce":"Quelle section faut-il écrire dans la case « ? » de la chaîne ?","aide":"C’est une section de 1924, entre 1922 et les deux dernières.","type":"choix","options":[{"id":"a","texte":"Mourir de ne pas mourir (1924)"},{"id":"b","texte":"L’Amour la poésie (1929)"},{"id":"c","texte":"Le Cœur à gaz (1923)"},{"id":"d","texte":"Capitale de la douleur (1926)"}],"multiple":false},{"enonce":"Complète le premier vers du poème « L’amoureuse ».","aide":"Le poème dit où se tient la femme aimée : sur une partie fine du visage.","type":"trous","segments":["« Elle est debout sur mes ",0," »"],"banque":["yeux","paupières","épaules","mains"]},{"enonce":"Relie chaque poème ou motif à ce que le cours en dit.","aide":"Pense au rôle des peintres dans le surréalisme.","type":"association","gauche":[{"id":"g0","texte":"« Ta chevelure d’oranges »"},{"id":"g1","texte":"« Max Ernst »"},{"id":"g2","texte":"Les sections expérimentales"}],"droite":[{"id":"d0","texte":"Nées de l’écriture automatique"},{"id":"d1","texte":"Le dialogue avec les peintres"},{"id":"d2","texte":"L’image comme éblouissement"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"La deuxième section est « **Mourir de ne pas mourir** » (1924), entre « Répétitions » (1922) et « Les Petits Justes »."},{"cle":{"type":"trous","trous":[["paupieres"]]},"affichage":"paupières","explication":"Le poème s’ouvre par « Elle est debout sur mes **paupières** » : la femme aimée est tout contre le regard du poète."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g0":"d2"}},"explication":"La chevelure d’oranges est une **image-éblouissement** ; « Max Ernst » dialogue avec **les peintres** ; les sections expérimentales naissent de **l’écriture automatique**."}]$ex$::jsonb),
  ('6ee991b6-1148-5de0-8784-defe34a258b7'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Une image simple et inouïe","competence":"argumenter","situation":"Lina croit que le surréalisme n’est qu’un jeu d’images étranges, sans amour. Hugo n’est pas d’accord. Lis leur échange et deux vers d’Éluard pour trancher.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Lina","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Lina","texte":"Chez Éluard, le surréalisme, c’est du délire sans sens : il n’y a pas d’amour là-dedans."},{"qui":"Hugo","texte":"Regarde les mots : la syntaxe est limpide, et le poème parle d’amour."},{"qui":"Lina","texte":"Mais les images sont étranges !"},{"qui":"Hugo","texte":"Oui, mais c’est un rapprochement qui déplace tout, pas un brouillard."}]},{"id":"vers","type":"texte","genre":"poeme","titre":"Les deux premiers vers","blocs":["La courbe de tes yeux fait le tour de mon cœur,","Un rond de danse et de douceur,"],"source":"Paul Éluard, « La courbe de tes yeux », *Capitale de la douleur* (1926), vers 1 et 2"}],"questions":[{"enonce":"Touche les deux mots par lesquels Hugo montre que le surréalisme d’Éluard n’est pas un délire.","aide":"Cherche un mot sur la clarté de la phrase et un mot sur le sujet.","type":"zone","document":"deb","multiple":true},{"enonce":"Touche les trois mots qui dessinent une forme circulaire autour du cœur.","aide":"Une courbe, un tour, un rond : cherche ce qui tourne.","type":"zone","document":"vers","multiple":true},{"enonce":"Range ces éléments : sont-ils des traits de forme ou ce que le recueil dit ?","aide":"La forme se voit sur la page ; le thème se lit dans le sens.","type":"categories","categories":[{"id":"c0","texte":"Trait de forme"},{"id":"c1","texte":"Ce que le recueil dit"}],"items":[{"id":"i0","texte":"L’absence et la séparation"},{"id":"i1","texte":"Refus de la ponctuation"},{"id":"i2","texte":"Le regard de la femme aimée"},{"id":"i3","texte":"Vers libres"},{"id":"i4","texte":"La souffrance amoureuse"},{"id":"i5","texte":"Syntaxe limpide"}]},{"enonce":"Quelle thèse ces éléments permettent-ils de défendre en dissertation ?","aide":"Pense au titre du recueil et à la femme dont les yeux reviennent sans cesse.","type":"choix","options":[{"id":"a","texte":"Le surréalisme interdit tout sentiment personnel"},{"id":"b","texte":"Le surréalisme d’Éluard est d’abord une poésie de l’amour"},{"id":"c","texte":"Le surréalisme n’est qu’un jeu de mots sans enjeu"},{"id":"d","texte":"Éluard refuse l’image au profit du récit"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24","m30"]},"explication":"La syntaxe **limpide** et le thème de l’**amour** montrent que le surréalisme d’Éluard sert l’amour : l’image est simple, et le sentiment, lisible."},{"cle":{"type":"zone","ids":["m1","m7","m12"]},"explication":"La **courbe**, le **tour** et le **rond** enlacent le cœur : les yeux de la femme aimée forment un cercle de douceur."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c0","i4":"c1","i5":"c0"}},"explication":"Les **vers libres**, l’absence de ponctuation et la syntaxe limpide sont des **traits de forme** ; l’amour, le regard et la douleur sont **ce que dit le recueil**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Le recueil montre que le surréalisme n’est pas qu’un jeu d’images étranges : c’est **une poésie de l’amour**, où la femme aimée rend le monde visible."}]$ex$::jsonb),
