  ('3c09146e-16e9-55c6-85ae-8024e63e0165'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Je ne mentirai pas","competence":"argumenter","situation":"Deux élèves se disputent : Carmen est-elle une séductrice qui perd don José, ou une femme qui refuse d’appartenir ? Lis leur échange et une scène écrite à la manière de Mérimée.","documents":[{"id":"scene","type":"texte","genre":"recit","titre":"Une scène imaginée","blocs":["Le brigadier la regarda longtemps sans parler. « Tu ne m’aimes donc plus ? » demanda-t-il enfin.","Elle ne baissa pas les yeux. « Non. Je pourrais te dire le contraire pour avoir la paix, mais je ne mentirai pas. Tu peux me tuer : je suis libre et je ne serai à personne. »"],"source":"Texte écrit pour l’exercice, à la manière de Mérimée, *Carmen*"},{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Zoé","emoji":"👧","cote":"gauche"},{"nom":"Tom","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Zoé","texte":"Carmen est une femme fatale : elle perd don José, c’est tout."},{"qui":"Tom","texte":"Non : c’est elle qui refuse d’appartenir à qui que ce soit, et le récit est mené par une voix d’homme."},{"qui":"Zoé","texte":"Donc on la voit à travers les yeux de José ?"},{"qui":"Tom","texte":"Et de l’archéologue : deux voix d’hommes."}]}],"questions":[{"enonce":"Touche le mot qui dit ce que le personnage refuse de faire, même pour avoir la paix.","aide":"C’est un verbe au futur, à la forme négative.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le mot qui dit ce que le personnage revendique.","aide":"Elle s’appartient à elle-même.","type":"zone","document":"scene","multiple":false},{"enonce":"Range chaque élément : correspond-il à Carmen, ou pas ?","aide":"Le cours dit qu’elle n’est pas une séductrice sans consistance.","type":"categories","categories":[{"id":"c0","texte":"Ce que Carmen est"},{"id":"c1","texte":"Ce qu’elle n’est pas"}],"items":[{"id":"i0","texte":"Un personnage secondaire du récit"},{"id":"i1","texte":"Une femme qui refuse d’appartenir"},{"id":"i2",