  ('0745ed3c-2759-5288-8243-2f91c0b98545'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"L’homme se fait-il lui-même ?","competence":"argumenter","situation":"Camille pense que Pic donne à l’homme une nature fixe. Éliott pense le contraire. Lis leur échange, puis construis l’argument de dissertation.","documents":[{"id":"deb","type":"dialogue","titre":"Le débat","modele":"bulles","participants":[{"nom":"Camille","emoji":"👧","cote":"gauche"},{"nom":"Éliott","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Camille","texte":"Pour Pic, l’homme a une nature fixe, comme le chat ou le cheval."},{"qui":"Éliott","texte":"Au contraire : Dieu ne lui a donné aucune place fixe, et il est ce qu’il se fait."},{"qui":"Camille","texte":"Alors tout dépend de l’éducation ?"},{"qui":"Éliott","texte":"Oui : si l’homme se fait, l’éducation est décisive."}]},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["L’homme n’a pas de nature fixe","Dieu ne lui a laissé ni place ni forme propre","?"],["Si l’homme se fait, l’éducation est tout","Il faut apprendre pour choisir de s’élever","Le projet de concilier les savoirs"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui montre qu’Éliott défend l’idée d’un homme qui se construit.","aide":"Le verbe « faire » à la forme réfléchie.","type":"zone","document":"deb","multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » du tableau ?","aide":"Il faut une scène du texte où l’homme reçoit une condition sans place fixe.","type":"choix","options":[{"id":"a","texte":"La scène où Dieu s’adresse à Adam"},{"id":"b","texte":"La publication par son neveu en 1496"},{"id":"c","texte":"Le cercle de Marsile Ficin à Florence"},{"id":"d","texte":"La condamnation des thèses par Innocent VIII en 1487"}],"multiple":false},{"enonce":"Range ces idées : Pic les affirme-t-il ou non ?","aide":"Pic veut concilier Platon, Aristote, la Kabbale et les Pères de l’Église.","type":"categories","categories":[{"id":"c0","texte":"Pic l’affirme"},{"id":"c1","texte":"Pic ne l’affirme pas"}],"items":[{"id":"i0","texte":"L’éducation est décisive"},{"id":"i1","texte":"Un seul philosophe détient toute la vérité"},{"id":"i2","texte":"Les philosophies peuvent s’accorder"},{"id":"i3","texte":"L’homme n’a pas de nature fixe"},{"id":"i4","texte":"L’homme est condamné à sa place dès sa naissance"}]},{"enonce":"Pourquoi ce texte est-il considéré comme un manifeste de l’humanisme ?","aide":"Le cours parle de confiance dans l’homme et de retour aux textes.","type":"choix","options":[{"id":"a","texte":"Il condamne le savoir des Anciens au profit de la foi"},{"id":"b","texte":"Il demande au pape d’interdire toute dispute savante"},{"id":"c","texte":"Il fait de la liberté et de l’éducation son centre"},{"id":"d","texte":"Il décrit fidèlement la vie de la cour de Florence"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"L’homme est ce qu’il se **fait** : il n’a pas de nature fixe, il se construit par ses choix."},{"cle":{"type":"choix","ids":["a"]},"explication":"La scène où **Dieu s’adresse à Adam** illustre que l’homme n’a ni place ni forme propre."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c0","i3":"c0","i4":"c1"}},"explication":"Pic affirme que l’homme **n’a pas de nature fixe**, que **l’éducation est décisive** et que les **philosophies peuvent s’accorder** ; il rejette une place imposée et le monopole d’un seul philosophe."},{"cle":{"type":"choix","ids":["c"]},"explication":"C’est un **manifeste de l’humanisme** parce qu’il fait de la **liberté** de l’homme et de l’**éducation** le centre de la dignité humaine."}]$ex$::jsonb),
  ('d573d7f6-9707-51ee-946c-2ec4353a0da1'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Une autrice qui réclame la tribune","competence":"se-reperer-temps","situation":"Tu prépares un exposé sur Olympe de Gouges. Place sa Déclaration dans le temps, puis relève sa carte d’identité.","documents":[{"id":"frise","type":"frise","titre":"Olympe de Gouges et les Françaises","debut":1740,"fin":1950,"pas":10,"evenements":[{"id":"z1","date":1748,"nom":"Naissance"},{"id":"z2","date":1791,"nom":"Sa Déclaration"},{"id":"z3","date":1944,"nom":"Vote des Françaises"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"Déclaration des droits de la femme et de la citoyenne","sousTitre":"Olympe de Gouges, 1791","emoji":"📜","lignes":[{"texte":"Autrice","valeur":"Marie Gouze, née à Montauban"},{"texte":"Dédiée à","valeur":"La reine Marie-Antoinette"},{"texte":"Nombre d’articles","valeur":"Dix-sept"},{"texte":"Modèle","valeur":"La Déclaration de 1789"},{"texte":"Objet d’étude","valeur":"?"}],"pied":"Publiée en septembre 1791","teinte":"violet"}],"questions":[{"enonce":"Sur la frise, touche l’année de publication de la Déclaration d’Olympe de Gouges.","aide":"Cherche l’événement qui porte le nom de son texte.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent la publication de la Déclaration du droit de vote des Françaises ?","aide":"Repère les deux dates sur la frise et soustrais.","type":"nombre","unite":"ans"},{"enonce":"Complète avec la carte d’identité du texte.","aide":"Relis les lignes « Dédiée à » et « Modèle » de la carte.","type":"trous","segments":["La Déclaration de 1791 est dédiée à la ",0," et reprend le texte de ",1,"."],"banque":["reine","Constituante","1789","1793"]},{"enonce":"Dans quel objet d’étude du programme range-t-on ce texte (la ligne « ? ») ?","aide":"C’est un texte qui défend une thèse et réclame des droits.","type":"choix","options":[{"id":"a","texte":"Le théâtre"},{"id":"b","texte":"La poésie"},{"id":"c","texte":"Le roman et le récit"},{"id":"d","texte":"La littérature d’idées"}],"multiple":false}]}$ex$::jsonb,
