  ('d573d7f6-9707-51ee-946c-2ec4353a0da1'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Cinq pièces pour un seul texte","competence":"analyser-texte","situation":"Pour ton oral, tu dois décrire la construction de la Déclaration, puis comparer son premier article à celui de 1789.","documents":[{"id":"parties","type":"tableau","titre":"Les parties du texte","colonnes":["Partie","Son contenu"],"lignes":[["Dédicace","Adressée à la reine"],["?","Au nom des « mères, filles, sœurs, représentantes de la nation »"],["Dix-sept articles","Dans l’ordre exact du texte de 1789"],["Postambule","Un appel enflammé : « Femme, réveille-toi »"]],"enteteLignes":true},{"id":"art1","type":"texte","genre":"source","titre":"Deux articles premiers","blocs":["1789 : « Les hommes naissent et demeurent libres et égaux en droits. »","1791 : « La femme naît libre et demeure égale à l’homme en droits. »"],"source":"Déclaration des droits de l’homme et du citoyen (1789), art. 1 ; Olympe de Gouges, Déclaration des droits de la femme et de la citoyenne (1791), art. 1"}],"questions":[{"enonce":"Quelle partie du texte se cache derrière la case « ? » ?","aide":"Elle ouvre le texte et parle au nom des femmes, avant les articles.","type":"choix","options":[{"id":"a","texte":"Le sommaire"},{"id":"b","texte":"L’avant-propos"},{"id":"c","texte":"Le préambule"},{"id":"d","texte":"Le contrat social"}],"multiple":false},{"enonce":"Touche la case qui montre que les articles suivent le texte de 1789.","aide":"Cherche l’idée d’un ordre identique.","type":"zone","document":"parties","multiple":false},{"enonce":"Touche le sujet de chacune des deux phrases, c’est-à-dire ceux qui naissent libres.","aide":"Cherche qui « naît » dans chaque phrase.","type":"zone","document":"art1","multiple":true},{"enonce":"Relie chaque partie du texte à ce à quoi ou à qui elle s’adresse.","aide":"Le registre change au postambule : il parle aux femmes.","type":"association","gauche":[{"id":"g0","texte":"La dédicace"},{"id":"g1","texte":"Le préambule"},{"id":"g2","texte":"Le postambule"},{"id":"g3","texte":