  ('d573d7f6-9707-51ee-946c-2ec4353a0da1'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Retourner 1789 contre ses oublis","competence":"argumenter","situation":"Deux élèves se demandent si recopier un texte, c’est le trahir ou l’utiliser. Lis leur échange, les phrases d’Olympe de Gouges, puis construis l’argument.","documents":[{"id":"deb","type":"dialogue","titre":"La copie est-elle une arme ?","modele":"bulles","participants":[{"nom":"Léa","emoji":"👧","cote":"gauche"},{"nom":"Sami","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Léa","texte":"Olympe de Gouges n’a rien inventé : elle recopie la Déclaration de 1789 en changeant deux ou trois mots."},{"qui":"Sami","texte":"Justement. En reprenant le texte fondateur mot pour mot, elle rend l’exclusion des femmes criante, sans avoir à la démontrer."},{"qui":"Léa","texte":"Donc la copie est une arme ?"},{"qui":"Sami","texte":"Oui : c’est un pastiche qui retourne les principes de 1789 contre leurs propres oublis."}]},{"id":"art","type":"texte","genre":"source","titre":"Article X et postambule","blocs":["Article X : « La femme a le droit de monter sur l’échafaud ; elle doit avoir également celui de monter à la tribune… »","Postambule : « Femme, réveille-toi ; le tocsin de la raison se fait entendre dans tout l’univers. »"],"source":"Olympe de Gouges, Déclaration des droits de la femme et de la citoyenne (1791), article X (début) et postambule"},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Les femmes sont des citoyennes à part entière","La loi les punit comme telles : elle doit aussi les représenter","?"],["Copier 1789 prouve l’oubli des femmes","Le texte est quasi identique : seules les personnes visées changent","L’article premier : « La femme naît libre… »"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui désigne ce que le pastiche rend criant.","aide":"Sami parle de ce que 1789 oubliait.","type":"zone","document":"deb","multiple":false},{"enonce":"Dans l’article X, touche les deux lieux que la citoyenne doit pouvoir atteindre.","aide":"Un lieu où l’on est puni, un lieu où l’on parle.","type":"zone","document":"art","multiple":true},{"enonce":"Quel est l’argument de l’article X ?","aide":"Si la loi s’applique aux femmes, que doit-elle leur reconnaître aussi ?","type":"choix","options":[{"id":"a","texte":"La loi punit les femmes : elle doit aussi les représenter"},{"id":"b","texte":"Les femmes doivent renoncer à l’échafaud pour obtenir le vote"},{"id":"c","texte":"Les femmes doivent être jugées plus sévèrement que les hommes"},{"id":"d","texte":"La tribune doit rester réservée aux hommes de loi"}],"multiple":false},{"enonce":"Quel exemple faut-il écrire dans la case « ? » de la première ligne du tableau ?","aide":"Cherche le passage qui montre la loi punissant les femmes.","type":"choix","options":[{"id":"a","texte":"Le contrat social entre l’homme et la femme"},{"id":"b","texte":"L’article X : l’échafaud et la tribune"},{"id":"c","texte":"La dédicace à la reine Marie-Antoinette"},{"id":"d","texte":"L’affiche Les Trois Urnes de 1793"}],"multiple":false},{"enonce":"Range chaque droit réclamé : il vise les femmes, ou d’autres exclus ?","aide":"Olympe de Gouges mène aussi d’autres combats de justice sociale.","type":"categories","categories":[{"id":"c0","texte":"Pour les femmes"},{"id":"c1","texte":"Pour d’autres exclus"}],"items":[{"id":"i0","texte":"Voter et être élue"},{"id":"i1","texte":"Monter à la tribune"},{"id":"i2","texte":"Abolir l’esclavage"},{"id":"i3","texte":"Protéger les enfants nés hors mariage"},{"id":"i4","texte":"Publier, s’exprimer librement"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m31"]},"explication":"Le pastiche rend **l’exclusion** des femmes criante : il suffit de comparer, sans autre démonstration."},{"cle":{"type":"zone","ids":["m11","m21"]},"explication":"L’article oppose l’**échafaud** (où la loi punit les femmes) à la **tribune** (où elles devraient parler)."},{"cle":{"type":"choix","ids":["a"]},"explication":"Puisque la loi **punit** les femmes comme des citoyennes, elle doit les **représenter** comme telles."},{"cle":{"type":"choix","ids":["b"]},"explication":"C’est **l’article X** : il oppose l’échafaud et la tribune."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Pour les **femmes** : tribune, vote, expression. Pour **d’autres exclus** : les esclaves et les enfants nés hors mariage."}]$ex$::jsonb),
