   $ex${"titre":"Un manifeste pour la langue française","competence":"se-reperer-temps","situation":"Tu fiches la Défense et illustration pour la classe : place-la entre l’ordonnance de Villers-Cotterêts et Les Regrets, puis lis sa carte d’identité.","documents":[{"id":"frise","type":"frise","titre":"Du Bellay et sa langue","debut":1520,"fin":1560,"pas":5,"evenements":[{"id":"z1","date":1522,"nom":"Naissance"},{"id":"z2","date":1539,"nom":"Villers-Cotterêts"},{"id":"z3","date":1549,"nom":"La Défense"},{"id":"z4","date":1558,"nom":"Les Regrets"}]},{"id":"carte","type":"fiche","modele":"affiche","entete":"Défense et illustration de la langue française","sousTitre":"Joachim du Bellay, 1549","emoji":"🖋️","lignes":[{"texte":"Forme","valeur":"Un manifeste en deux livres"},{"texte":"Parle au nom de","valeur":"?"},{"texte":"Accompagne le recueil","valeur":"L’Olive"},{"texte":"Veut prouver que","valeur":"Le français vaut le latin et le grec"}],"pied":"Un manifeste de jeunes poètes","teinte":"violet"}],"questions":[{"enonce":"Touche l’année de parution du manifeste.","aide":"Le manifeste porte le nom de son titre court.","type":"zone","document":"frise","multiple":false},{"enonce":"Combien d’années séparent l’ordonnance de Villers-Cotterêts du manifeste ?","aide":"Soustrais les deux dates de la frise.","type":"nombre","unite":"ans"},{"enonce":"Au nom de quel groupe Du Bellay parle-t-il (la ligne « ? ») ?","aide":"Ce groupe de jeunes poètes comprend Ronsard.","type":"choix","options":[{"id":"a","texte":"Les Surréalistes"},{"id":"b","texte":"Le Parnasse"},{"id":"c","texte":"Les Philosophes"},{"id":"d","texte":"La Pléiade"}],"multiple":false},{"enonce":"Touche le recueil de sonnets que Du Bellay écrit à Rome.","aide":"Ce n’est pas un manifeste : c’est un recueil de poèmes, écrit plus tard.","type":"zone","document":"frise","multiple":false}]}$ex$::jsonb,
