  ('32c2bd2c-065d-5c4a-951e-8c31f735073d'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les quatre thèses du manifeste","competence":"analyser-texte","situation":"Tu dois résumer le manifeste en quatre idées et dire ce qu’il demande aux poètes. Lis le tableau puis le résumé.","documents":[{"id":"theses","type":"tableau","titre":"Les quatre thèses","colonnes":["Thèse","Ce qu’elle affirme"],"lignes":[["?","Le français n’est pas pauvre par nature : il l’est par manque de culture"],["Illustrer","Imiter les Anciens et les Italiens en créant, sans les traduire"],["Enrichir","Emprunter au grec, au latin, aux dialectes, aux métiers ; inventer des mots"],["Abandonner","Les formes médiévales jugées basses"]],"enteteLignes":true},{"id":"res","type":"texte","genre":"article","titre":"Le programme en quelques lignes","blocs":["Le poète doit laisser de côté les rondeaux, les ballades et les virelais, formes médiévales jugées trop basses. À leur place, il s’essaiera au sonnet, à l’ode, à l’élégie et à la tragédie à l’antique.","Mais l’inspiration ne suffit pas : il faut polir longuement son œuvre et la soumettre à la « lime » d’un lecteur savant."],"source":"Résumé écrit pour l’exercice, d’après la Défense et illustration de la langue française (1549)"}],"questions":[{"enonce":"Quel verbe se cache derrière la case « ? » ?","aide":"Trois verbes sont déjà dans le tableau : il en manque un, celui du titre.","type":"choix","options":[{"id":"a","texte":"Enrichir"},{"id":"b","texte":"Illustrer"},{"id":"c","texte":"Défendre"},{"id":"d","texte":"Abandonner"}],"multiple":false},{"enonce":"Touche la case qui explique comment enrichir le vocabulaire.","aide":"Cherche les emprunts et les mots inventés.","type":"zone","document":"theses","multiple":false},{"enonce":"Touche les trois formes médiévales que le manifeste demande d’abandonner.","aide":"Elles sont citées avant le sonnet et l’ode.","type":"zone","document":"res","multiple":true},{"enonce":"Complète la dernière phrase du résumé.","aide":"Relis le second paragraphe du résumé.","type":"trous","segments":["Le poète doit polir son œuvre et la soumettre à la « ",0," » d’un lecteur savant."],"banque":["loupe","règle","plume","lime"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Le premier verbe du titre est **Défendre** : le français n’est pas pauvre par nature."},{"cle":{"type":"zone","ids":["r2c1"]},"explication":"On enrichit la langue par **emprunts** (grec, latin, dialectes, métiers) et par **néologismes**."},{"cle":{"type":"zone","ids":["m7","m9","m12"]},"explication":"Le manifeste condamne **rondeaux, ballades et virelais**, jugés trop bas."},{"cle":{"type":"trous","trous":[["lime"]]},"affichage":"lime","explication":"L’inspiration ne suffit pas : l’œuvre passe sous **la lime** d’un lecteur savant, c’est-à-dire qu’on la polit."}]$ex$::jsonb),
  ('32c2bd2c-065d-5c4a-951e-8c31f735073d'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Imiter, ce n’est pas traduire","competence":"argumenter","situation":"Deux élèves se disputent sur le mot « imitation » chez Du Bellay. Un passage célèbre sur les Romains les départage.","documents":[{"id":"rom","type":"texte","genre":"source","titre":"Les Romains et les Grecs","blocs":["« … se transformant en eux, les dévorant, et après les avoir bien digérés, les convertissant en sang et nourriture… »"],"source":"Joachim du Bellay, Défense et illustration de la langue française (1549), à propos de l’imitation des Grecs par les Romains ; orthographe modernisée"},{"id":"deb","type":"dialogue","titre":"Imiter ou traduire ?","modele":"bulles","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Théo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"Imiter les Anciens, pour Du Bellay, c’est les traduire le plus fidèlement possible."},{"qui":"Théo","texte":"Non : il refuse de traduire. Il faut faire en français ce qu’ils ont fait dans leur langue."},{"qui":"Inès","texte":"Alors imiter, c’est s’en nourrir pour créer autre chose ?"},{"qui":"Théo","texte":"Oui, comme le dit l’image des Romains qui digèrent les Grecs."}]},{"id":"arg","type":"tableau","titre":"Un argument à compléter","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Imiter, ce n’est pas traduire","Il faut faire en français ce que les Anciens ont fait dans leur langue","?"],["Le poète doit travailler","L’inspiration ne suffit pas","La « lime » d’un lecteur savant"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le verbe qu’Inès emploie à tort pour définir l’imitation.","aide":"Théo la corrige en disant ce que Du Bellay refuse.","type":"zone","document":"deb","multiple":false},{"enonce":"Touche les deux participes qui montrent l’imitation comme une nourriture.","aide":"Cherche ce qu’on fait d’un aliment.","type":"zone","document":"rom","multiple":true},{"enonce":"Quel exemple, tiré de l’œuvre de Du Bellay lui-même, applique ce programme (la case « ? ») ?","aide":"Les trois autres sonnets sont de Rimbaud et de Baudelaire.","type":"choix","options":[{"id":"a","texte":"« Le Dormeur du val », sonnet de Rimbaud"},{"id":"b","texte":"« Correspondances », sonnet de Baudelaire"},{"id":"c","texte":"« Heureux qui, comme Ulysse », sonnet des Regrets"},{"id":"d","texte":"« Les Chats », sonnet de Baudelaire"}],"multiple":false},{"enonce":"Relie chaque procédé du passage à son effet.","aide":"Pense à ce que fait l’image, à ce que prouve l’exemple, et à ce que dit le rythme.","type":"association","gauche":[{"id":"g0","texte":"Le verbe « dévorer »"},{"id":"g1","texte":"L’exemple des Romains"},{"id":"g2","texte":"La suite de participes"}],"droite":[{"id":"d0","texte":"Une autorité historique qui appuie la thèse"},{"id":"d1","texte":"L’imitation est une appropriation, pas une copie"},{"id":"d2","texte":"Un rythme qui suit les étapes de la transformation"}]},{"enonce":"Quelle formule de dissertation ce passage appuie-t-il le mieux ?","aide":"Les Romains ne se contentent pas de copier : ils transforment ce qu’ils prennent.","type":"choix","options":[{"id":"a","texte":"Créer, c’est rejeter tout ce que les Anciens ont écrit"},{"id":"b","texte":"Traduire est la seule façon d’enrichir une langue"},{"id":"c","texte":"Imiter, c’est copier fidèlement pour préserver la tradition"},{"id":"d","texte":"Imiter, c’est s’approprier un modèle pour créer à son tour"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m9"]},"explication":"Du Bellay refuse de **traduire** : il veut créer en français, pas transposer."},{"cle":{"type":"zone","ids":["m5","m11"]},"explication":"Les Romains **dévorent** puis **digèrent** les Grecs : imiter, c’est assimiler pour en faire sa propre substance."},{"cle":{"type":"choix","ids":["c"]},"explication":"Dans *Les Regrets*, le sonnet **« Heureux qui, comme Ulysse »** applique le programme : une forme et un thème antiques refaits en français."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g2":"d2"}},"explication":"Le **verbe** dit l’appropriation, l’**exemple** donne une autorité, la **suite de participes** déroule la transformation étape par étape."},{"cle":{"type":"choix","ids":["d"]},"explication":"L’image de la digestion montre que **l’imitation est une appropriation créatrice**."}]$ex$::jsonb),
  ('4a5df7ee-b174-594d-ae6d-392e1c39c5a5'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Deux amis dans un ranch","competence":"se-reperer-temps","situation":"Tu prépares une fiche sur Des souris et des hommes. Repère les personnages du ranch et place le roman dans la vie de Steinbeck.","documents":[{"id":"persos","type":"tableau","titre":"Qui est qui ?","colonnes":["Personnage","Qui il est"],"lignes":[["George Milton","Petit et vif : il pense pour deux"],["Lennie Small","?"],["Candy","Le vieux manchot"],["Crooks","Le palefrenier noir, tenu à l’écart"],["Curley","Le fils du patron, agressif"],["Leur rêve","Acheter une petite ferme et y soigner des lapins"]],"enteteLignes":true},{"id":"frise","type":"frise","titre":"Steinbeck et son roman","debut":1900,"fin":1970,"pas":10,"evenements":[{"id":"z1","date":1902,"nom":"Naissance"},{"id":"z2","date":1937,"nom":"Le roman"},{"id":"z3","date":1962,"nom":"Prix Nobel"}]}],"questions":[{"enonce":"Touche le personnage que les autres ouvriers tiennent à l’écart.","aide":"Il est palefrenier, et noir.","type":"zone","document":"persos","multiple":false},{"enonce":"Qui est Lennie, dans la case « ? » ?","aide":"Il aime caresser ce qui est doux sans mesurer sa force.","type":"choix","options":[{"id":"a","texte":"Un vieux conteur qui a perdu ses dents"},{"id":"b","texte":"Un colosse doux et déficient mental"},{"id":"c","texte":"Un jeune berger muet et solitaire"},{"id":"d","texte":"Un contremaître rusé et sans pitié"}],"multiple":false},{"enonce":"Combien d’années séparent la parution du roman du prix Nobel de Steinbeck ?","aide":"Lis les deux dates sur la frise.","type":"nombre","unite":"ans"},{"enonce":"Complète le rêve des deux hommes.","aide":"Regarde la dernière ligne du tableau.","type":"trous","segments":["Leur rêve : acheter une petite ",0," et y soigner des ",1,"."],"banque":["chevaux","boutique","lapins","ferme"]}]}$ex$::jsonb,
