  ('4a5df7ee-b174-594d-ae6d-392e1c39c5a5'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Du chiot au Luger","competence":"analyser-texte","situation":"Tu dois raconter l’intrigue puis montrer comment deux morts se répondent. Lis la chaîne des étapes et le résumé.","documents":[{"id":"fil","type":"chaine","titre":"Le fil du roman","disposition":"colonne","noeuds":[{"id":"z1","texte":"Arrivée de George et Lennie dans un ranch"},{"id":"z2","texte":"Lennie tue un chiot sans le vouloir"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Lennie s’enfuit, traqué par les hommes"},{"id":"z5","texte":"George lui redit le rêve de la ferme"},{"id":"z6","texte":"George le tue pour lui épargner le lynchage"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"},{"de":"z5","a":"z6"}]},{"id":"morts","type":"texte","genre":"recit","titre":"Deux morts qui se répondent","blocs":["Au ranch, Carlson abat le vieux chien de Candy d’une balle dans la nuque, « pour son bien ». Candy regrette de ne pas l’avoir fait lui-même.","À la fin, George abat Lennie de la même manière, avec le Luger de Carlson."],"source":"Résumé écrit pour l’exercice, d’après le roman de Steinbeck (1937)"}],"questions":[{"enonce":"Que se passe-t-il à l’étape « ? » de la chaîne ?","aide":"Après le chiot, Lennie caresse quelque chose de doux dans la grange.","type":"choix","options":[{"id":"a","texte":"Lennie tue accidentellement la femme de Curley"},{"id":"b","texte":"Lennie part seul chercher du travail ailleurs"},{"id":"c","texte":"Lennie tue Carlson avec son Luger"},{"id":"d","texte":"Lennie sauve le chiot qu’il vient de blesser"}],"multiple":false},{"enonce":"Touche l’arme avec laquelle George tue Lennie.","aide":"Elle appartenait à Carlson.","type":"zone","document":"morts","multiple":false},{"enonce":"Touche l’endroit où la balle est tirée, la même pour le chien et pour Lennie.","aide":"Le texte précise la partie du corps visée.","type":"zone","document":"morts","multiple":false},{"enonce":"Relie chaque épisode à ce qu’il annonce ou à ce qu’il porte.","aide":"Cherche les signes qui annoncent la chute.","type":"association","gauche":[{"id":"g0","texte":"Le chiot et les souris tués"},{"id":"g1","texte":"Le chien de Candy abattu"},{"id":"g2","texte":"Le rêve de la ferme"}],"droite":[{"id":"d0","texte":"Ce qui tient George et Lennie ensemble"},{"id":"d1","texte":"La mort de Lennie"},{"id":"d2","texte":"Les gestes mortels d’un Lennie qui ne mesure pas sa force"}]}]}$ex$::jsonb,
