  ('4a5df7ee-b174-594d-ae6d-392e1c39c5a5'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Ceux qui n’ont personne","competence":"argumenter","situation":"Le refrain de George revient comme une prière. Lis une scène écrite à la manière du roman, puis démonte ses thèmes.","documents":[{"id":"scene","type":"texte","genre":"theatre","titre":"Au bord de la rivière","blocs":[{"didascalie":"Le soir, près d’une rivière. Un petit feu. Lennie regarde les flammes."},{"personnage":"George","replique":"Dis-moi, Lennie : les autres types, ils ont quoi ?"},{"personnage":"Lennie","replique":"Ils n’ont personne."},{"personnage":"George","replique":"Et nous ?"},{"personnage":"Lennie","replique":"Nous, on a chacun l’autre. Et un jour on aura la ferme, avec les lapins."}],"source":"Texte écrit pour l’exercice, à la manière de Steinbeck, Des souris et des hommes"},{"id":"arg","type":"tableau","titre":"Deux lectures à prouver","colonnes":["Thèse","Argument","Exemple"],"lignes":[["Le rêve de la ferme est inaccessible","Il est répété comme une prière, mais tout bascule","?"],["La solitude touche presque tous les personnages","Chacun dit sa solitude","Crooks, le palefrenier noir, tenu à l’écart"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le mot qui dit la solitude des autres ouvriers.","aide":"Lennie complète la phrase de George.","type":"zone","document":"scene","multiple":false},{"enonce":"Touche le mot qui dit ce qui lie George et Lennie.","aide":"Chacun a quelqu’un sur qui veiller.","type":"zone","document":"scene","multiple":false},{"enonce":"Relie chaque thème du roman à ce qu’il porte.","aide":"Pense aux personnages les plus faibles.","type":"association","gauche":[{"id":"g0","texte":"La solitude"},{"id":"g1","texte":"L’amitié"},{"id":"g2","texte":"Le rêve américain"},{"id":"g3","texte":"La brutalité"}],"droite":[{"id":"d0","texte":"Elle frappe Candy, Crooks, Lennie"},{"id":"d1","texte":"Chaque personnage la dit"},{"id":"d2","texte":"Ce qui distingue George et Lennie des autres"},{"id":"d3","texte":"Il reste inaccessible"}]},{"enonce":"Quel exemple faut-il écrire dans la case « ? » ?","aide":"Le rêve est raconté une dernière fois… juste avant la fin.","type":"choix","options":[{"id":"a","texte":"Le récit du rêve, puis la mort de Lennie"},{"id":"b","texte":"L’achat de la ferme grâce à Candy"},{"id":"c","texte":"La promotion de George par Slim"},{"id":"d","texte":"Le mariage de Curley et de sa femme"}],"multiple":false},{"enonce":"Range chaque élément : il dit la solitude, ou l’amitié ?","aide":"Demande-toi : la personne est-elle seule, ou liée à quelqu’un ?","type":"categories","categories":[{"id":"c0","texte":"Solitude"},{"id":"c1","texte":"Amitié"}],"items":[{"id":"i0","texte":"Crooks, tenu à l’écart"},{"id":"i1","texte":"George et Lennie qui se veillent l’un l’autre"},{"id":"i2","texte":"Le rêve de la ferme à deux"},{"id":"i3","texte":"La femme de Curley, qui s’ennuie"},{"id":"i4","texte":"Les autres ouvriers, qui n’ont personne"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m24"]},"explication":"Les autres n’ont **personne** : c’est la solitude que le refrain oppose à l’amitié des deux héros."},{"cle":{"type":"zone","ids":["m30"]},"explication":"Ils ont **chacun** l’autre : l’amitié est ce qui les distingue de tous."},{"cle":{"type":"association","paires":{"g3":"d0","g0":"d1","g1":"d2","g2":"d3"}},"explication":"La **solitude**, l’**amitié**, le **rêve** inaccessible et la **brutalité** sont les quatre thèmes de la fiche."},{"cle":{"type":"choix","ids":["a"]},"explication":"George raconte une dernière fois le rêve, puis tire : **le rêve reste inaccessible**."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c1","i2":"c1","i3":"c0","i4":"c0"}},"explication":"Crooks, la femme de Curley et les ouvriers sont seuls ; George et Lennie, et leur **rêve à deux**, sont liés."}]$ex$::jsonb),
  ('f115fdbf-fffc-5357-a0e6-cf648b843705'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Deux récits, un désert","competence":"se-reperer-temps","situation":"Tu prépares un oral sur Désert. Repère qui est qui dans les deux récits, puis lis la fiche du roman.","documents":[{"id":"persos","type":"tableau","titre":"Les personnages","colonnes":["Personnage","Qui il est"],"lignes":[["Ma el Aïnine","Le cheikh qui guide les hommes bleus vers le nord"],["Nour","Un enfant des hommes bleus"],["Lalla","Une jeune descendante des nomades"],["Le Hartani","?"]],"enteteLignes":true},{"id":"carte","type":"fiche","modele":"affiche","entete":"Désert","sousTitre":"J.-M. G. Le Clézio, 1980","emoji":"🏜️","lignes":[{"texte":"Auteur","valeur":"Né à Nice, en 1940"},{"texte":"Prix du roman","valeur":"Grand prix Paul-Morand (1980)"},{"texte":"Année du prix Nobel","valeur":"?"},{"texte":"Genre","valeur":"Un roman à deux récits alternés"}],"pied":"Un roman du désert et de l’exil","teinte":"violet"}],"questions":[{"enonce":"Qui est le Hartani (la case « ? ») ?","aide":"C’est le père de l’enfant de Lalla.","type":"choix","options":[{"id":"a","texte":"Le jeune berger muet que Lalla aime"},{"id":"b","texte":"Le vieux pêcheur qui raconte des histoires"},{"id":"c","texte":"Le jeune mendiant de Marseille"},{"id":"d","texte":"Le cheikh qui conduit les hommes bleus"}],"multiple":false},{"enonce":"Range chaque personnage dans le récit auquel il appartient.","aide":"Un récit parle des hommes bleus, l’autre de leur descendante.","type":"categories","categories":[{"id":"c0","texte":"Récit de 1909-1912"},{"id":"c1","texte":"Récit contemporain"}],"items":[{"id":"i0","texte":"Lalla"},{"id":"i1","texte":"Nour"},{"id":"i2","texte":"Ma el Aïnine"},{"id":"i3","texte":"Le Hartani"}]},{"enonce":"En quelle année Le Clézio reçoit-il le prix Nobel de littérature (la ligne « ? ») ?","aide":"Le roman date de 1980 ; le Nobel vient bien plus tard.","type":"choix","options":[{"id":"a","texte":"1980"},{"id":"b","texte":"1963"},{"id":"c","texte":"1940"},{"id":"d","texte":"2008"}],"multiple":false},{"enonce":"Combien d’années séparent le grand prix Paul-Morand du prix Nobel ?","aide":"Prends l’année du roman sur la fiche et celle du Nobel.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
