  ('f115fdbf-fffc-5357-a0e6-cf648b843705'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"De Lalla à la dune","competence":"analyser-texte","situation":"Tu dois suivre le parcours de Lalla puis montrer comment l’écriture fait éprouver le désert.","documents":[{"id":"fil","type":"chaine","titre":"Le parcours de Lalla","disposition":"colonne","noeuds":[{"id":"z1","texte":"Lalla grandit dans un bidonville marocain"},{"id":"z2","texte":"Elle refuse un mariage arrangé"},{"id":"z3","texte":"?"},{"id":"z4","texte":"Elle connaît un bref succès de modèle photo"},{"id":"z5","texte":"Retour au désert : elle accouche sous un arbre"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z5"}]},{"id":"dune","type":"texte","genre":"recit","titre":"Sur la dune","blocs":["Sur la plaine, le sable est chaud. Le vent ne s’arrête pas. Les hommes marchent vers le nord, derrière le cheikh. La lumière est blanche."],"source":"Texte écrit pour l’exercice, à la manière de Désert de Le Clézio"}],"questions":[{"enonce":"Que fait Lalla à l’étape « ? » ?","aide":"Après le bidonville et avant le succès de modèle, elle change de ville et de pays.","type":"choix","options":[{"id":"a","texte":"Elle devient bergère dans le désert"},{"id":"b","texte":"Elle retourne chez sa tante Aamma"},{"id":"c","texte":"Elle épouse le Hartani à Marseille"},{"id":"d","texte":"Elle quitte le Maroc pour Marseille"}],"multiple":false},{"enonce":"Touche l’étape où Lalla refuse de se laisser marier.","aide":"Cherche le mot « refuse ».","type":"zone","document":"fil","multiple":false},{"enonce":"Le cours cite quatre éléments sensoriels : lumière, sable, vent, chaleur. Retrouve-les dans le passage.","aide":"La chaleur s’écrit ici avec un adjectif.","type":"zone","document":"dune","multiple":true},{"enonce":"Relie chaque caractéristique du roman à son effet.","aide":"Pense à ce qu’on ressent en lisant, au rythme, et à la construction.","type":"association","gauche":[{"id":"g0","texte":"Une écriture sensorielle"},{"id":"g1","texte":"Une écriture lente"},{"id":"g2","texte":"Deux récits alternés"}],"droite":[{"id":"d0","texte":"La contemplation l’emporte sur l’action"},{"id":"d1","texte":"Une histoire collective et un destin individuel se répondent"},{"id":"d2","texte":"On éprouve le désert"}]}]}$ex$::jsonb,
