  ('f115fdbf-fffc-5357-a0e6-cf648b843705'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Une ville plus hostile que le désert","competence":"argumenter","situation":"Lalla arrive à Marseille. Deux élèves ne lisent pas la ville de la même façon : à toi de trancher avec le texte.","documents":[{"id":"ville","type":"texte","genre":"recit","titre":"Marseille","blocs":["À Marseille, les rues sont sombres et l’air sent le gasoil. Lalla avance dans la foule et personne ne la regarde. Aux fenêtres, les volets restent fermés.","Elle pense au désert, à la lumière claire et au silence."],"source":"Texte écrit pour l’exercice, à la manière de Désert de Le Clézio"},{"id":"deb","type":"dialogue","titre":"Refuge ou exil ?","modele":"bulles","participants":[{"nom":"Nina","emoji":"👧","cote":"gauche"},{"nom":"Hugo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Nina","texte":"Pour Lalla, la ville est un refuge : on l’y accueille enfin."},{"qui":"Hugo","texte":"Le passage montre le contraire : à Marseille, elle est dépossédée une seconde fois."},{"qui":"Nina","texte":"Alors le désert, c’est le vrai chez-soi ?"},{"qui":"Hugo","texte":"Oui : la liberté, la pureté, la mémoire des ancêtres."}]}],"questions":[{"enonce":"Touche les quatre mots qui disent l’hostilité de la ville.","aide":"Cherche ce qui est sombre, sale, indifférent, clos.","type":"zone","document":"ville","multiple":true},{"enonce":"Touche le mot de Nina que le passage contredit.","aide":"Le texte montre une ville qui rejette Lalla.","type":"zone","document":"deb","multiple":false},{"enonce":"Quelle lecture le passage prouve-t-il ?","aide":"Compte les mots hostiles, puis regarde ce que Lalla évoque.","type":"choix","options":[{"id":"a","texte":"Le désert est un lieu aussi bruyant que la ville"},{"id":"b","texte":"La ville est plus hostile que le désert : un nouvel exil"},{"id":"c","texte":"Lalla se sent chez elle parmi les foules marseillaises"},{"id":"d","texte":"La ville offre à Lalla la liberté qu’elle cherchait"}],"multiple":false},{"enonce":"Relie chaque thème de Désert à ce qu’il dénonce ou célèbre.","aide":"Deux thèmes dénoncent, un thème célèbre.","type":"association","gauche":[{"id":"g0","texte":"La destruction des peuples nomades"},{"id":"g1","texte":"L’exil urbain"},{"id":"g2","texte":"Le retour au désert"}],"droite":[{"id":"d0","texte":"La liberté, la pureté et la mémoire des ancêtres"},{"id":"d1","texte":"Un effet de la colonisation"},{"id":"d2","texte":"Une seconde dépossession"}]},{"enonce":"Range chaque élément : il appartient au désert, ou à la ville ?","aide":"Les deux lieux s’opposent dans tout le roman.","type":"categories","categories":[{"id":"c0","texte":"Le désert"},{"id":"c1","texte":"La ville"}],"items":[{"id":"i0","texte":"Le silence et la lumière"},{"id":"i1","texte":"Liberté et pureté"},{"id":"i2","texte":"Un bref succès de modèle photographique"},{"id":"i3","texte":"La misère des immigrés"},{"id":"i4","texte":"Mémoire des ancêtres"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m5","m11","m18","m27"]},"explication":"La ville est **sombre**, sent le **gasoil**, ignore Lalla (**personne**) et reste **fermée**."},{"cle":{"type":"zone","ids":["m6"]},"explication":"La ville n’est pas un **refuge** : elle est vécue comme une seconde dépossession."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les mots de la ville sont hostiles, ceux du désert doux : l’exil urbain est **plus hostile que le désert**."},{"cle":{"type":"association","paires":{"g2":"d0","g0":"d1","g1":"d2"}},"explication":"La **colonisation** détruit les nomades, l’**exil** dépossède une seconde fois, le **désert** reste le lieu de la liberté."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c0","i2":"c1","i3":"c1","i4":"c0"}},"explication":"Liberté, mémoire et lumière sont du côté du **désert** ; misère et succès éphémère sont ceux de la **ville**."}]$ex$::jsonb),
