  ('46b8470d-33e8-5de1-9f17-28283aa4eb65'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Cent piqûres plutôt qu’un traité","competence":"argumenter","situation":"Peut-on combattre un préjugé par un traité ? Lis un article écrit à la manière de Voltaire, puis un échange entre deux élèves.","documents":[{"id":"zele","type":"texte","genre":"article","titre":"Article « Zèle »","blocs":["Un homme fort zélé jugea qu’on ne pouvait honorer Dieu qu’en brûlant son voisin. Il en brûla un, puis deux, puis dix, et s’en alla dormir fort content de sa bonté."],"source":"Texte écrit pour l’exercice, à la manière de Voltaire"},{"id":"deb","type":"dialogue","titre":"Voltaire approuve-t-il ?","modele":"bulles","participants":[{"nom":"Clara","emoji":"👧","cote":"gauche"},{"nom":"Yanis","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Clara","texte":"Voltaire approuve donc celui qui brûle son voisin ?"},{"qui":"Yanis","texte":"Non : il feint d’approuver pour mieux dénoncer. C’est de l’ironie."},{"qui":"Clara","texte":"Et pourquoi un article si court ?"},{"qui":"Yanis","texte":"Parce qu’on ne combat pas un préjugé par un traité, mais par cent piqûres."}]}],"questions":[{"enonce":"Touche les deux mots qui, pris ironiquement, louent le fanatique.","aide":"Cherche les mots qui sonnent comme des qualités.","type":"zone","document":"zele","multiple":true},{"enonce":"Touche le verbe qui explique le procédé de Voltaire.","aide":"Yanis dit qu’il fait semblant.","type":"zone","document":"deb","multiple":false},{"enonce":"Relie chaque caractéristique du livre à son rôle.","aide":"Pense à l’effet sur le lecteur, et à la censure.","type":"association","gauche":[{"id":"g0","texte":"L’ironie"},{"id":"g1","texte":"Le récit bref"},{"id":"g2","texte":"Le format portatif"}],"droite":[{"id":"d0","texte":"Il rend l’argument vivant"},{"id":"d1","texte":"Elle dénonce en feignant d’approuver"},{"id":"d2","texte":"Il circule facilement et se cache"}]},{"enonce":"Range chaque élément : il rend le livre difficile à censurer, ou l’argument vivant ?","aide":"Un groupe concerne l’objet